head.script:
scwin.CHART_DATA_URL ="/ui/sample/SBChart/MAP/data/MAP_MULTI.json";   // {json:[...좌표 지점...]}
scwin.CHART_CONFIG = {
    global: { size: { width: 460, height: 460 } },
    dataOpts: {
        keys: { x: "code", value: ["강수량"] },
        labels: true
    },
    extend: {
        map: {
            mapUrl: "/websquare/_websquare_/externalJS/sbchart/SIGUNGU.json",
            drillDown: true,
            mapColor: { hoverColor: "#FDE1E1" },
            panel: {                                            // ★ 멀티 지점 패널
                type: "vlabel",
                useMulti: true,
                useAreaAndPanel: true,
                vlabelRectColor: "green",
                vlabelAapStyle: { strokeColor: "red", strokeWidth: 5, strokeOpacity: 0.7 },
                format: function (code, label, data) { return data["강수량"] + " mm"; }
            }
        }
    }
};

scwin.onpageload = async function () {
    var res = await $c.sbm.executeDynamic({ id: "sbm_sbchart", action: scwin.CHART_DATA_URL, method: "get", mediatype: "application/json", mode: "asynchronous", isProcessMsg: false });
    var data = res.responseJSON;
    $c.ext.drawChartData("map", data, chartWrap, scwin.CHART_CONFIG);
};
